onClick:
{{
  (() => {
    JSutils.resetInactivityTimer();
    const store = appsmith.store;
    const formData = {
      ani002_id:                 InputID.text,
      ani002_nome:               (Input1Nome.text || '').trim().toUpperCase(),
      ani002_tipo:               Select1Especie.selectedOptionValue,
      ani002_raca:               Select1Raca.selectedOptionValue,
      ani002_sexo:               Select1Sexo.selectedOptionValue,
      ani002_castrado:           Select1Castrado.selectedOptionValue,
      ani002_porte:              Select1Porte.selectedOptionValue,
      ani002_pelagem:            Select1Pelagem.selectedOptionValue,
      ani002_cor:                Select1Cor.selectedOptionValue,
      ani002_temp:               Select1Temperamento.selectedOptionValue,
      ani002_convivio:           Select1Convivio.selectedOptionValue,
      ani002_vet:                Select1Veterinario.selectedOptionValue,
      ani002_clinica:            Select1Clinica.selectedOptionValue,
      ani002_peso:               Input3Peso.text || null,
      ani002_registro:           (Input3Registro.text || '').trim().toUpperCase(),
      ani002_microchip:          (Input3Microchip.text || '').trim().toUpperCase(),
      ani002_canil:              (Input1Canil.text || '').trim().toUpperCase(),
      ani002_registro_pedigree:  (Input1Pedigree.text || '').trim().toUpperCase(),
      ani002_nome_registro:      (Input1PedigreeNome.text || '').trim().toUpperCase(),
      ani002_observacao:         (Input1Observacao.text || '').trim().toUpperCase(),
      ani002_datanasc:           DatePicker1Nascimento.selectedDate ? moment(DatePicker1Nascimento.selectedDate).format('YYYY-MM-DD') : null,
      ani002_data_obito:         DatePicker1Obito.selectedDate ? moment(DatePicker1Obito.selectedDate).format('YYYY-MM-DD') : null,
      ani002_tutor:              store.petSelecionado?.ani002_tutor || null,
      ani002_imagem:             store.petSelecionado?.ani002_imagem || null
    };
    const acao = store.modalContexto?.acaoTipo;
    return JSconfirmation.showModal({
      action: acao === 'ADICIONAR' ? 'Insert' : 'Update',
      message: acao === 'ADICIONAR' ? 'Deseja salvar este novo pet?' : 'Deseja salvar as alterações?',
      icon: acao === 'ADICIONAR' ? 'plus' : 'edit',
      color: acao === 'ADICIONAR' ? 'green' : 'orange',
      row: formData
    });
  })()
}}
